function readSearchForm(){return {country:$('#country').value.trim(),area:$('#area').value.trim(),pickup:$('#pickup').value.trim(),destination:$('#destination').value.trim(),date:$('#rideDate').value,time:$('#rideTime').value}}
function initSearch(){const form=$('#rideSearchForm');if(!form)return;const date=$('#rideDate');if(date){const t=new Date();date.min=`${t.getFullYear()}-${String(t.getMonth()+1).padStart(2,'0')}-${String(t.getDate()).padStart(2,'0')}`;date.value=date.min}form.addEventListener('submit',e=>{e.preventDefault();const q=readSearchForm();location.href='find-ride.html?'+new URLSearchParams(q).toString()})}
async function renderDrivers(q){const container=$('#driverResults');if(!container)return;container.innerHTML='<div class="empty-state"><h3>Searching online drivers…</h3><p>Checking routes and prices.</p></div>';const norm=s=>String(s||'').trim().toLowerCase();try{const snap=await getDocs(query(collection(db,'drivers'),where('online','==',true)));const matches=[];snap.forEach(ds=>{const d=ds.data();if(!d.name||d.registrationStage!=='routes'||d.verificationStatus==='rejected'||d.moderationStatus==='suspended'||d.emailVerified!==true||norm(d.country)!==norm(q.country)||norm(d.area)!==norm(q.area))return;(d.routes||[]).forEach((r,i)=>{const p=norm(q.pickup),dest=norm(q.destination),from=norm(r.from),to=norm(r.to);if(p&&dest&&(from===p||from.includes(p)||p.includes(from))&&(to===dest||to.includes(dest)||dest.includes(to)))matches.push({d,id:ds.id,r,routeIndex:i})})});$('#resultCount').textContent=`${matches.length} online driver${matches.length===1?'':'s'} found`;if(!matches.length){container.innerHTML='<div class="empty-state"><div class="empty-icon">⌖</div><h3>No matching online drivers yet</h3><p>Try another pickup, destination or area. Drivers appear only when their availability is on.</p></div>';return}container.innerHTML=matches.map(({d,id,r,routeIndex})=>`<article class="driver-card"><div class="driver-card-top">${d.photo?`<img class="driver-avatar" src="${esc(d.photo)}" alt="">`:`<div class="driver-avatar">${esc((d.name||'D').charAt(0))}</div>`}<div><h3>${esc(d.name)}</h3><p>${esc(d.area)}, ${esc(d.country)}</p></div><span class="online-tag">● ONLINE</span></div>${d.vehiclePhoto?`<img class="vehicle-img" src="${esc(d.vehiclePhoto)}" alt="Vehicle">`:'<div class="vehicle-img" style="display:grid;place-items:center;font-size:38px">🚘</div>'}<div class="driver-card-body"><div class="vehicle-title">${esc(d.vehicleMake)} · ${esc(d.vehicleType)}</div><div class="vehicle-meta">${esc(d.vehicleYear)} · ${esc(d.vehicleColor)} · ${esc(d.seats)} passenger seats<br>${esc(d.vehicleNotes||'Vehicle details supplied by driver')}</div><div class="route-price"><div><small>Driver's price</small><strong>${money(r.price,r.currency)}</strong></div><span class="route-label">${esc(r.from)}<br>↓<br>${esc(r.to)}</span></div><button class="btn btn-primary btn-block book-driver" data-driver="${esc(id)}" data-route="${routeIndex}">View and request ride →</button></div></article>`).join('');$$('.book-driver',container).forEach(b=>b.onclick=()=>{const url=new URLSearchParams({...q,driver:b.dataset.driver,route:b.dataset.route});const u=userNow();if(!u)location.href='login.html?next='+encodeURIComponent('book-ride.html?'+url);else location.href='book-ride.html?'+url})}catch(e){console.error(e);container.innerHTML='<div class="empty-state"><h3>Could not load drivers</h3><p>Check Firestore setup and rules.</p></div>';$('#resultCount').textContent='Search unavailable'}}
function initFindRide(){if(document.body.dataset.page!=='findride')return;const p=new URLSearchParams(location.search);['country','area','pickup','destination','date','time'].forEach(k=>{const el=$('#'+(k==='date'?'rideDate':k==='time'?'rideTime':k));if(el&&p.get(k))el.value=p.get(k)});const t=new Date(),today=`${t.getFullYear()}-${String(t.getMonth()+1).padStart(2,'0')}-${String(t.getDate()).padStart(2,'0')}`;$('#rideDate').min=today;if(!$('#rideDate').value)$('#rideDate').value=today;const q=readSearchForm();if(q.country&&q.area&&q.pickup&&q.destination)renderDrivers(q);$('#rideSearchForm').addEventListener('submit',e=>{e.preventDefault();const q=readSearchForm();history.replaceState({},'',`find-ride.html?${new URLSearchParams(q)}`);renderDrivers(q)})}
async function initBookingPage(){const form=$('#bookingForm');if(!form)return;const p=new URLSearchParams(location.search),driverId=p.get('driver'),routeIndex=Number(p.get('route'));let driver,route;try{const s=await getDoc(doc(db,'drivers',driverId));if(!s.exists())throw Error('Driver not found');driver=s.data();route=driver.routes?.[routeIndex];if(!route||!driver.online)throw Error('This driver or route is no longer available.');$('#selectedDriver').innerHTML=`<h3>${esc(driver.name)} · ${esc(driver.vehicleMake)}</h3><p>${esc(route.from)} → ${esc(route.to)}</p><strong>${money(route.price,route.currency)}</strong><p class="muted">${esc(driver.area)}, ${esc(driver.country)}</p>`;const t=new Date(),today=`${t.getFullYear()}-${String(t.getMonth()+1).padStart(2,'0')}-${String(t.getDate()).padStart(2,'0')}`;$('#bookDate').min=today;$('#bookDate').value=p.get('date')||today;$('#bookTime').value=p.get('time')||''}catch(e){$('#selectedDriver').textContent=e.message;form.querySelector('button[type="submit"]').disabled=true;return}form.addEventListener('submit',async e=>{e.preventDefault();const u=userNow();if(!u){location.href='login.html?next='+encodeURIComponent(location.pathname+location.search);return}if(!u.emailVerified){toast(verifyText);return}try{if(await accountRole(u)!=='passenger')throw Error('Only passenger accounts can request rides. Log out and sign in with a passenger account.');const prof=await getDoc(doc(db,'users',u.uid));const passenger=prof.exists()?prof.data():{};if(['suspended','pending_review'].includes(passenger.moderationStatus))throw Error('Your account is suspended. Open your dashboard to correct the information requested by admin.');await addDoc(collection(db,'bookings'),{driverId,driverName:driver.name,driverPhone:driver.phone,passengerId:u.uid,passengerName:passenger.name||u.displayName||u.email,passengerPhone:$('#passengerPhoneBooking').value.trim(),country:driver.country,area:driver.area,pickup:route.from,destination:route.to,date:$('#bookDate').value,time:$('#bookTime').value,notes:$('#bookingNote').value.trim(),price:route.price,currency:route.currency,status:'pending',createdAt:serverTimestamp()});toast('Ride request sent to driver.');setTimeout(()=>location.href='bookings.html',500)}catch(err){toast(err.message||'Could not send request.')}})}
function initLogin(){const form=$('#loginForm');if(!form)return;form.addEventListener('submit',async e=>{e.preventDefault();const mode=e.submitter?.value||'login',role=$('#loginRole').value,email=$('#loginEmail').value.trim(),password=$('#loginPassword').value;try{if(mode==='register'){if(role!=='passenger')throw Error('Start driver registration from Become a driver.');const name=$('#passengerName').value.trim(),phone=$('#passengerPhone').value.trim();if(!name||!phone)throw Error('Enter your name and phone number.');const c=await createUserWithEmailAndPassword(auth,email,password);await updateProfile(c.user,{displayName:name});const passengerData={uid:c.user.uid,role:'passenger',name,phone,email:c.user.email,createdAt:serverTimestamp(),moderationStatus:'normal'};await setDoc(doc(db,'users',c.user.uid),passengerData);await notifyAdminNewProfile(c.user.uid,'passenger',passengerData);await sendEmailVerification(c.user);await signOut(auth);toast('Account created. Verify your email, then log in.');return}const c=await signInWithEmailAndPassword(auth,email,password);if(!c.user.emailVerified){try{await sendEmailVerification(c.user)}catch(_){}await signOut(auth);throw Error('Email not verified. A verification link has been sent if possible.')}const actual=await accountRole(c.user);if(!actual)throw Error('No RideConnect profile found for this account.');if(actual==='admin'){location.href='admin.html';return}if(role!==actual)throw Error(actual==='driver'?'Choose Driver as your account type.':'Choose Passenger as your account type.');if(actual==='driver'){const d=await getDoc(doc(db,'drivers',c.user.uid));if(d.exists())await updateDoc(doc(db,'drivers',c.user.uid),{emailVerified:true,updatedAt:serverTimestamp()});const stage=d.data()?.registrationStage;if(['suspended','pending_review'].includes(d.data()?.moderationStatus)){location.href='driver-dashboard.html';return}if(stage!=='routes'){location.href=`driver.html?stage=${({profile:'licence',licence:'vehicle',vehicle:'routes'}[stage]||'routes')}`;return}location.href='driver-dashboard.html'}else{const next=new URLSearchParams(location.search).get('next');location.href=next||'bookings.html'}}catch(err){toast(err.code==='auth/email-already-in-use'?'This email is already registered. Please log in.':err.code==='auth/invalid-credential'?'Email or password is incorrect.':err.message||'Could not continue.')}})}
function cancellationReason(){return new Promise(resolve=>{const old=$('#reasonModal');old?.remove();const box=document.createElement('div');box.id='reasonModal';box.style.cssText='position:fixed;inset:0;background:#102a4399;z-index:99;display:grid;place-items:center;padding:18px';box.innerHTML=`<form class="panel-form" style="width:min(100%,420px)"><h2>Cancel this ride?</h2><p class="muted">Give the driver a reason so they know not to travel.</p><div class="field"><label for="cancelReason">Reason for cancellation *</label><textarea id="cancelReason" required minlength="3" maxlength="500" rows="4" placeholder="Tell the driver why you are cancelling"></textarea></div><div class="field-row"><button type="button" class="btn btn-outline" id="keepRide">Keep ride</button><button class="btn btn-primary" type="submit">Confirm cancellation</button></div></form>`;document.body.append(box);box.querySelector('form').onsubmit=e=>{e.preventDefault();const v=$('#cancelReason').value.trim();if(!v)return;box.remove();resolve(v)};$('#keepRide').onclick=()=>{box.remove();resolve(null)}})}
function initBookings(){const root=$('#bookingsList');if(!root)return;let tab=new URLSearchParams(location.search).get('view')==='driver'?'driver':'passenger';async function render(){const u=userNow();if(!u){root.innerHTML='<div class="empty-state"><h3>Please log in</h3><a class="btn btn-primary" href="login.html">Log in</a></div>';return}if(!u.emailVerified){root.innerHTML=`<div class="empty-state"><h3>Verify your email first</h3><p>${verifyText}</p></div>`;return}const role=await accountRole(u);if(role==='driver')tab='driver';if(role!=='driver')tab='passenger';if(role==='driver'){const dp=await getDoc(doc(db,'drivers',u.uid));if(dp.exists()&&dp.data().moderationStatus==='suspended'){root.innerHTML='<div id="correctionHost"></div>';await initCorrectionPanel(root,'driver',u.uid);return}}if(role==='passenger'){const profileSnap=await getDoc(doc(db,'users',u.uid));if(profileSnap.exists()&&['suspended','pending_review'].includes(profileSnap.data().moderationStatus)){root.innerHTML='<div id="correctionHost"></div>';await initCorrectionPanel(root,'passenger',u.uid);return}}$$('[data-tab]').forEach(b=>{b.hidden=(b.dataset.tab==='driver'&&role!=='driver')||(b.dataset.tab==='passenger'&&role==='driver');b.classList.toggle('active',b.dataset.tab===tab)});root.innerHTML='<div class="empty-state">Loading requests…</div>';try{const snap=await getDocs(query(collection(db,'bookings'),where(tab==='driver'?'driverId':'passengerId','==',u.uid)));const rows=[];snap.forEach(s=>rows.push({id:s.id,...s.data()}));rows.sort((a,b)=>(b.createdAt?.seconds||0)-(a.createdAt?.seconds||0));if(!rows.length){root.innerHTML=`<div class="empty-state"><h3>No ${tab==='driver'?'driver requests':'ride requests'} yet</h3><p>${tab==='driver'?'Requests from passengers appear here.':'Search for drivers to request a ride.'}</p><a class="btn btn-primary" href="index.html">Find a ride</a></div>`;return}root.innerHTML=rows.map(b=>`<article class="booking-card"><div><h3>${esc(b.pickup)} → ${esc(b.destination)}</h3><p>${esc(b.date)} at ${esc(b.time)} · ${esc(b.area)}, ${esc(b.country)}<br>${tab==='driver'?'Passenger':'Driver'}: ${esc(tab==='driver'?b.passengerName:b.driverName)} · ${money(b.price,b.currency)}${b.notes?'<br>Notes: '+esc(b.notes):''}${b.cancellationReason?'<br>Cancellation reason: '+esc(b.cancellationReason):''}</p><span class="status ${esc(b.status)}">${esc(String(b.status).toUpperCase())}</span></div><div class="booking-actions">${tab==='driver'&&b.status==='pending'?`<button class="btn btn-primary btn-small" data-action="accepted" data-id="${esc(b.id)}">Accept</button><button class="btn btn-outline btn-small" data-action="declined" data-id="${esc(b.id)}">Decline</button>`:''}${tab==='passenger'&&['pending','accepted'].includes(b.status)?`<button class="btn btn-outline btn-small" data-action="cancelled" data-id="${esc(b.id)}">Cancel ride</button>`:''}</div></article>`).join('');$$('[data-action]',root).forEach(b=>b.onclick=async()=>{try{const action=b.dataset.action;let reason='';if(action==='cancelled'){reason=await cancellationReason();if(reason===null)return}const refDoc=doc(db,'bookings',b.dataset.id);const fresh=await getDoc(refDoc);if(!fresh.exists())throw Error('Request no longer exists.');const data=fresh.data();if(tab==='passenger'&&(data.passengerId!==u.uid||!['pending','accepted'].includes(data.status)))throw Error('This ride can no longer be cancelled.');if(tab==='driver'&&(data.driverId!==u.uid||data.status!=='pending'))throw Error('This request can no longer be updated.');await updateDoc(refDoc,{status:action,...(action==='cancelled'?{cancellationReason:reason,cancelledBy:'passenger'}:{}),updatedAt:serverTimestamp()});toast(action==='cancelled'?'Ride cancelled. The driver can see your reason.':`Request ${action}.`);render()}catch(e){toast(e.message||'Could not update request. Check Firestore rules.')}})}catch(e){console.error(e);root.innerHTML='<div class="empty-state"><h3>Could not load requests</h3><p>Check Firestore rules and connection.</p></div>'}}onAuthStateChanged(auth,render)}
async function initDriverDashboard(){const root=$('#driverDashboard');if(!root)return;onAuthStateChanged(auth,async u=>{if(!u)return;if(!u.emailVerified){root.innerHTML=`<div class="empty-state"><h3>Verify your email</h3><p>${verifyText}</p></div>`;return}if(await accountRole(u)!=='driver'){root.innerHTML='<div class="empty-state"><h3>Driver account required</h3></div>';return}const refDoc=doc(db,'drivers',u.uid);async function draw(){const s=await getDoc(refDoc);if(!s.exists()){root.innerHTML='<div class="empty-state"><h3>Driver profile missing</h3><a href="driver.html">Complete registration</a></div>';return}const d=s.data();if(d.moderationStatus==='suspended'||d.moderationStatus==='pending_review'){root.innerHTML='<div id="correctionHost"></div>';await initCorrectionPanel(root,'driver',u.uid);return}root.innerHTML=`<div class="panel-form"><div class="section-title"><div><span class="eyebrow">DRIVER DASHBOARD</span><h2>Welcome, ${esc(d.name)}</h2><p class="muted">${esc(d.area)}, ${esc(d.country)}</p></div><label class="toggle-row"><input type="checkbox" id="onlineToggle" ${d.online?'checked':''}><span><b>${d.online?'Online — visible in search':'Offline — hidden from search'}</b><small>Turn off when you are unavailable.</small></span></label></div><p>Licence review: <b>${esc(d.verificationStatus||'pending')}</b></p><a class="btn btn-primary" href="bookings.html?view=driver">View passenger ride requests →</a></div><div class="panel-form" style="margin-top:20px"><h2>Your routes and prices</h2><div id="dashboardRoutes" class="route-list">${(d.routes||[]).map((r,i)=>`<form class="route-item route-edit" data-index="${i}"><div class="route-item-head"><span class="route-number">Route ${i+1}</span><button type="button" class="route-remove" data-delete="${i}">Delete</button></div><div class="field-row"><div class="field"><label>Pickup</label><input name="from" required value="${esc(r.from)}"></div><div class="field"><label>Destination</label><input name="to" required value="${esc(r.to)}"></div></div><div class="field-row"><div class="field"><label>Price</label><input name="price" type="number" min="1" step="any" required value="${esc(r.price)}"></div><div class="field"><label>Currency</label><input name="currency" required maxlength="8" value="${esc(r.currency)}"></div></div><div class="field"><label>Notes</label><input name="notes" value="${esc(r.notes||'')}"></div><button class="btn btn-outline btn-small" type="submit">Save changes</button></form>`).join('')||'<p class="muted">No routes yet. Add your first route below.</p>'}</div><h3>Add another route</h3><form id="newRoute" class="route-item"><div class="field-row"><div class="field"><label>Pickup</label><input name="from" required></div><div class="field"><label>Destination</label><input name="to" required></div></div><div class="field-row"><div class="field"><label>Price</label><input name="price" type="number" min="1" step="any" required></div><div class="field"><label>Currency</label><input name="currency" value="NGN" required maxlength="8"></div></div><div class="field"><label>Notes</label><input name="notes"></div><button class="btn btn-primary btn-small" type="submit">Add route</button></form></div>`;$('#onlineToggle').onchange=async e=>{await updateDoc(refDoc,{online:e.target.checked,updatedAt:serverTimestamp()});toast(e.target.checked?'You are now online and visible in searches.':'You are offline and hidden from searches.');draw()};$$('.route-edit').forEach(f=>f.onsubmit=async e=>{e.preventDefault();const routes=[...(d.routes||[])],i=Number(f.dataset.index),fd=new FormData(f);routes[i]={from:fd.get('from').trim(),to:fd.get('to').trim(),price:Number(fd.get('price')),currency:fd.get('currency').trim().toUpperCase(),notes:fd.get('notes').trim()};await updateDoc(refDoc,{routes,updatedAt:serverTimestamp()});toast('Route updated.');draw()});$$('[data-delete]').forEach(b=>b.onclick=async()=>{if(!confirm('Delete this route?'))return;const routes=[...(d.routes||[])];routes.splice(Number(b.dataset.delete),1);await updateDoc(refDoc,{routes,updatedAt:serverTimestamp()});toast('Route deleted.');draw()});$('#newRoute').onsubmit=async e=>{e.preventDefault();const fd=new FormData(e.currentTarget),routes=[...(d.routes||[])];if(routes.length>=20)return toast('Maximum 20 routes.');routes.push({from:fd.get('from').trim(),to:fd.get('to').trim(),price:Number(fd.get('price')),currency:fd.get('currency').trim().toUpperCase(),notes:fd.get('notes').trim()});await updateDoc(refDoc,{routes,updatedAt:serverTimestamp()});toast('New route added.');draw()}}await draw()})}
document.addEventListener('DOMContentLoaded',()=>{$$('[data-year]').forEach(x=>x.textContent=new Date().getFullYear());initDriver();initSearch();initFindRide();initBookingPage();initLogin();initBookings();initDriverDashboard();initAdmin();initNavigation()});
